def focus_for(d):
    """Draw-tube position (mm past the focus for infinity) that focuses a screen d metres away."""
    return SC_F * SC_F / (d - SC_F) * 1000


def hms(s, dec=0):
    t = s % 86400
    h, m, x = int(t // 3600), int(t % 3600 // 60), t % 60
    return "%02d:%02d:" % (h, m) + (("%0" + str(3 + dec) + "." + str(dec) + "f") % x if dec else "%02d" % int(x))


def grey(v):
    v = max(0, min(255, int(v)))
    return "#%02x%02x%02x" % (v, v, min(255, v + 8))


